    pub const HOWTOPLAY_THECRAFTINGTABLE_TITLE: &str = "howtoplay.theCraftingTable.title";
    #[doc = "Ready to take your crafting to the next level? Place four planks in a square in your crafting grid, and you'll get a §ecrafting table§f :crafting_table: - a whole new way to craft."]
    pub const HOWTOPLAY_THECRAFTINGTABLE_TEXT_1: &str = "howtoplay.theCraftingTable.text.1";
    #[doc = "Place your crafting table in the world, then right-click it to open it. The larger crafting grid will let you make bigger and better things, including tools, beds, and doors."]
    pub const HOWTOPLAY_THECRAFTINGTABLE_TEXT_2_KEYBOARD: &str =
        "howtoplay.theCraftingTable.text.2.keyboard";
