    pub const HOWTOPLAY_THECRAFTINGTABLE_TEXT_2_GAMEPAD: &str =
        "howtoplay.theCraftingTable.text.2.gamepad";
    #[doc = "Place your crafting table in the world, then tap it to open it. The larger crafting grid will let you make bigger and better things, including tools, beds, and doors."]
    pub const HOWTOPLAY_THECRAFTINGTABLE_TEXT_2_TOUCH: &str =
        "howtoplay.theCraftingTable.text.2.touch";
    #[doc = "The End"]
    pub const HOWTOPLAY_THEEND: &str = "howtoplay.theEnd";
    #[doc = "The End is another dimension which can be accessed through an active End Portal. The End Portal can be found in a Stronghold, which is deep underground in the Overworld."]
    pub const HOWTOPLAY_THEEND_TEXT_1: &str = "howtoplay.theEnd.text.1";
    #[doc = "Every End Portal Frame block is missing something mysterious to bring out the power within."]
    pub const HOWTOPLAY_THEEND_TEXT_2: &str = "howtoplay.theEnd.text.2";
    #[doc = "The Other Side"]
    pub const HOWTOPLAY_THEEND_HEADER_1: &str = "howtoplay.theEnd.header.1";
    #[doc = "Once the portal is active, jump into it to go to The End."]
    pub const HOWTOPLAY_THEEND_TEXT_3: &str = "howtoplay.theEnd.text.3";
    #[doc = "The End is home to the dreaded Ender Dragon. She is a fierce and powerful enemy and seems to draw power from strange crystals. Her breath and fireball attacks leave lingering acid across the battlefield. Bring some friends to ensure your victory!"]
    pub const HOWTOPLAY_THEEND_TEXT_4: &str = "howtoplay.theEnd.text.4";
    #[doc = "If once wasn't enough, add four End Crystals to the exit portal corners to reawaken the Ender Dragon."]
    pub const HOWTOPLAY_THEEND_TEXT_5: &str = "howtoplay.theEnd.text.5";
    #[doc = "Textures"]
    pub const HOWTOPLAY_TEXTURES: &str = "howtoplay.textures";
    #[doc = "Texture packs visually transform the game's appearance, applying a fresh coat of paint to your Minecraft world."]
    pub const HOWTOPLAY_TEXTURES_TEXT_1: &str = "howtoplay.textures.text.1";
    #[doc = "Tools"]
    pub const HOWTOPLAY_TOOLS: &str = "howtoplay.tools";
    #[doc = "There are many tools in Minecraft that will allow you mine blocks faster than your fist. Tools can be crafted from Wood, Stone, Iron, Gold, Diamond, or Netherite."]
    pub const HOWTOPLAY_TOOLS_TEXT_1: &str = "howtoplay.tools.text.1";
    #[doc = "Using the right tool for the job will not only mine that block faster, but will also lose less durability. More complex tools must be created in order to mine rarer resources."]
    pub const HOWTOPLAY_TOOLS_TEXT_2: &str = "howtoplay.tools.text.2";
    #[doc = "Tools that Break Stuff"]
    pub const HOWTOPLAY_TOOLS_HEADER_1: &str = "howtoplay.tools.header.1";
    #[doc = "The Pickaxe is good at breaking hard blocks like Cobblestone, Iron, or Furnaces."]
    pub const HOWTOPLAY_TOOLS_TEXT_3: &str = "howtoplay.tools.text.3";
